WITH RANKED_RELATIONSHIPS AS (
SELECT
    l.LNK_POSITION_HRREPRESENTATIVE_OWNERID_HKEY AS LNK_POSITION_HRREPRESENTATIVE_OWNERID_HKEY,
    l.POSITION_HKEY AS POSITION_HKEY,
    l.HR_REPRESENTATIVE_OWNERID_HKEY AS HR_REPRESENTATIVE_OWNERID_HKEY,

    -- TODO: use generated tag instead of well-known name _CURRENT_ACTIVE_TIMESTAMP
    ls._CURRENT_ACTIVE_TIMESTAMP AS _CURRENT_RELATIONSHIP_TIMESTAMP, -- was ls.LOAD_DATE

    ROW_NUMBER() OVER (
        PARTITION BY l.POSITION_HKEY -- parent hub hk
        ORDER BY ls._CURRENT_ACTIVE_TIMESTAMP DESC -- TODO: as above. Was ls.LOAD_DATE
    ) AS row_num

FROM {{ source('eli_dv_rv', 'lnk_position_hrrepresentative_ownerid') }} l
INNER JOIN {{ ref('lks_erc_position_hrrepresentative_ownerid_curr') }} ls
    ON l.LNK_POSITION_HRREPRESENTATIVE_OWNERID_HKEY = ls.LNK_POSITION_HRREPRESENTATIVE_OWNERID_HKEY
)

SELECT * EXCLUDE (row_num)
FROM RANKED_RELATIONSHIPS
WHERE row_num = 1
